1. SELECT a.asset_name, a.capacity_mw FROM assets a WHERE a.capacity_mw > 100 ORDER BY a.asset_name;
2. SELECT a.asset_name, a.capacity_mw FROM assets a JOIN sensor_readings s ON a.asset_id = s.asset_id AND s.unit = 'MW' WHERE a.capacity_mw > 100 ORDER BY a.asset_name;
3. SELECT a.asset_name, a.capacity_mw FROM assets a JOIN asset_types t ON a.asset_type_id = t.asset_type_id WHERE a.capacity_mw > 100 ORDER BY a.asset_name;
